test("čtyři zachované palety mají znak po znaku produkční hodnoty", () => {
  const drift = [];
  for (const [id, expected] of Object.entries(PRODUCTION)) {
    const got = resolveTheme(id, false);
    for (const [k, v] of Object.entries(expected)) {
      if (got[k] !== v) drift.push(`${id}.${k}: ${v} → ${got[k]}`);
    }
  }
  assert.deepEqual(drift, [], "zachovaná paleta se pohnula:\n" + drift.join("\n"));
});

test("zachovaná paleta si přinesla i nové role, ale nepřepsala staré", () => {
  for (const id of Object.keys(PRODUCTION)) {
    const t = resolveTheme(id, false);
    /* Žádná ze čtyř zachovaných palet si vyvýšenou plochu nenavrhla, takže
       jí je karta — přesně jak to bylo, než token existoval. Dopočítaná
       „raised" plocha z V1 zůstává pod svým starým jménem a se svou starou
       hodnotou; dnes ji nečte žádná komponenta. */
    assert.equal(t.elevatedSurface, t.card, `${id}: vyvýšená plocha se dopočítala, i když ji nikdo nenavrhl`);
    assert.ok(t.surfaceRaised, `${id} přišel o starší alias surfaceRaised`);
    assert.equal(t.placeholderText, t.placeholder, `${id}: nápověda nesmí mít dvě různé hodnoty`);
    assert.equal(t.polarity, t.mode, `${id}: polarita a režim jsou totéž`);
  }
});

test("zachovaná paleta nemá vlastní stavovou ani datovou tabulku", () => {
  // Právě proto se jim po V2 nehnula ani stavová barva: neladí je, dědí
  // sdílenou FUNCTIONAL / CHART, přesně jako ve V1.1.
  const shared = resolveTheme("signature-day", false);
  const mul = resolveTheme("mulberry-paper", false);
  assert.equal(mul.successFg, shared.successFg);
  assert.equal(mul.errorBg, shared.errorBg);
  assert.equal(mul.chart1, shared.chart1);
});

test("zrušené protějšky v aktivním výběru nejsou", () => {
  // River light, Teal light, Mulberry dark a celé tři rodiny odešly.
  for (const gone of ["river-mist", "teal-parchment", "atlantic-sky", "clay-alabaster",
    "olive-gold", "river-light", "teal-light", "mulberry-dark", "signature"]) {
    assert.equal(FIXED_PRESET_IDS.indexOf(gone), -1, `${gone} se vrátil do výběru`);
  }
});
